  useEffect(()=>{if(!user)return;void refreshUnread();const timer=window.setInterval(refreshUnread,30000);return()=>window.clearInterval(timer);},[user,refreshUnread]);
  useEffect(()=>{if(workspaceId){loadPages(workspaceId).catch(e=>notify((e as Error).message));api<{items:Page[]}>(`/recent?workspaceId=${encodeURIComponent(workspaceId)}`).then(r=>setRecentPages(r.items)).catch(()=>setRecentPages([]));}},[workspaceId,loadPages]);
  useEffect(()=>{const timer=window.setTimeout(()=>{if(query.trim().length<2){setSearchPages([]);return;}api<{items:Page[]}>(`/search?workspaceId=${encodeURIComponent(workspaceId)}&q=${encodeURIComponent(query.trim())}`).then(r=>setSearchPages(r.items)).catch(()=>setSearchPages([]));},220);return()=>window.clearTimeout(timer);},[query,workspaceId]);
  useEffect(()=>{const handler=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearchOpen(true);document.querySelector<HTMLInputElement>('.top-center input')?.focus();}if(e.key==='Escape')setSearchOpen(false);};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler);},[]);
  useEffect(()=>{if(active){setPageTitle(active.title);setPageIcon(active.icon||'📄');}},[active?.id]);
  if(busy)return <div className="splash"><div className="brand-mark">00</div><span>공간을 불러오는 중</span></div>;
  if(!user)return <LoginScreen/>;
  const visiblePages=query.trim().length>=2?searchPages:favoritesOnly?pages.filter(page=>page.favorite):recentOnly?recentPages:pages.filter(page=>`${page.title} ${page.icon}`.toLowerCase().includes(query.toLowerCase()));
  const pageDepth=(page:Page)=>{let depth=0,parent=page.parent_id;const seen=new Set<string>([page.id]);while(parent&&depth<8&&!seen.has(parent)){seen.add(parent);const row=pages.find(item=>item.id===parent);if(!row)break;depth++;parent=row.parent_id;}return depth;};
  const treeEntries=(()=>{if(query.trim().length>=2||favoritesOnly||recentOnly)return visiblePages.map(page=>({page,depth:pageDepth(page)}));const byId=new Map(pages.map(page=>[page.id,page])),children=new Map<string|null,Page[]>();for(const page of pages){const parent=page.parent_id&&byId.has(page.parent_id)?page.parent_id:null;children.set(parent,[...(children.get(parent)||[]),page]);}for(const list of children.values())list.sort((a,b)=>b.updated_at.localeCompare(a.updated_at));const output:Array<{page:Page;depth:number}>=[],visited=new Set<string>();const walk=(parent:string|null,depth:number)=>{for(const page of children.get(parent)||[]){if(visited.has(page.id))continue;visited.add(page.id);output.push({page,depth});walk(page.id,Math.min(depth+1,8));}};walk(null,0);for(const page of pages)if(!visited.has(page.id)){output.push({page,depth:0});visited.add(page.id);walk(page.id,1);}return output;})();
  async function openPage(page:Page){setPageId(page.id);setRailOpen(false);setFavoritesOnly(false);setRecentOnly(false);void api(`/pages/${page.id}/visit`,{method:'POST'}).then(()=>api<{items:Page[]}>(`/recent?workspaceId=${encodeURIComponent(workspaceId)}`).then(r=>setRecentPages(r.items))).catch(()=>{});}
