  function insertBlock(type:string){if(!editor)return;const chain=editor.chain().focus();if(type==='paragraph')chain.setParagraph().run();if(type==='h1')chain.toggleHeading({level:1}).run();if(type==='h2')chain.toggleHeading({level:2}).run();if(type==='h3')chain.toggleHeading({level:3}).run();if(type==='bullet')chain.toggleBulletList().run();if(type==='ordered')chain.toggleOrderedList().run();if(type==='checklist')chain.toggleTaskList().run();if(type==='quote')chain.toggleBlockquote().run();if(type==='code')chain.toggleCodeBlock().run();if(type==='table')chain.insertTable({rows:3,cols:3,withHeaderRow:true}).run();setBlockMenuOpen(false);}
