      <div className="connection-line"><span className={`connection-dot ${connection.status}`}/><span>{pending?`저장 대기 ${pending}건`:connection.label}</span><span className="local-label"><Check size={13}/> 이 기기에도 임시 저장</span></div>
      {blockMenuOpen&&<div className="block-menu" role="menu" aria-label="블록 삽입"><div className="block-menu-title">블록 유형 선택</div>{[['paragraph','텍스트','기본 문단'],['h1','제목 1','큰 제목'],['h2','제목 2','중간 제목'],['h3','제목 3','작은 제목'],['bullet','글머리 목록','항목 목록'],['ordered','번호 목록','순서 있는 항목'],['checklist','체크리스트','완료 상태를 함께 관리'],['quote','인용','강조 인용'],['code','코드 블록','코드 또는 명령'],['table','표','3×3 표']].map(([type,title,description])=><button key={type} role="menuitem" onMouseDown={event=>event.preventDefault()} onClick={()=>insertBlock(type)}><b>{title}</b><small>{description}</small></button>)}<button className="block-menu-close" onClick={()=>setBlockMenuOpen(false)}>닫기 <kbd>Esc</kbd></button></div>}
