type WorkspaceMember={id:string;email:string;display_name:string;role:string;joined_at:string};
type WorkspaceInvite={id:string;email:string;role:string;created_at:string};
function MembersDialog({workspaceId,onClose,notify}:{workspaceId:string;onClose:()=>void;notify:(message:string)=>void}){
  const[members,setMembers]=useState<WorkspaceMember[]>([]),[invites,setInvites]=useState<WorkspaceInvite[]>([]),[canManage,setCanManage]=useState(false),[canAssignAdmin,setCanAssignAdmin]=useState(false),[email,setEmail]=useState(''),[role,setRole]=useState('member'),[busy,setBusy]=useState(true);
  const load=async()=>{setBusy(true);try{const result=await api<{members:WorkspaceMember[];invites:WorkspaceInvite[];canManage:boolean;canAssignAdmin:boolean}>(`/workspaces/${workspaceId}/members`);setMembers(result.members);setInvites(result.invites);setCanManage(result.canManage);setCanAssignAdmin(result.canAssignAdmin);}catch(error){notify((error as Error).message);}finally{setBusy(false);}};
  useEffect(()=>{void load();},[workspaceId]);
  async function invite(){if(!email.trim())return;try{const result=await api<{accepted:boolean;invitationSent?:boolean}>(`/workspaces/${workspaceId}/invites`,{method:'POST',body:JSON.stringify({email,role})});setEmail('');notify(result.accepted?'멤버를 워크스페이스에 추가했습니다.':result.invitationSent?'초대 메일을 보냈습니다.':'초대는 등록했지만 메일을 보내지 못했습니다. 서비스 주소를 초대 대상에게 전달해 주세요.');await load();}catch(error){notify((error as Error).message);}}
  async function changeRole(member:WorkspaceMember,next:string){try{await api(`/workspaces/${workspaceId}/members/${member.id}`,{method:'PATCH',body:JSON.stringify({role:next})});await load();notify('멤버 역할을 변경했습니다.');}catch(error){notify((error as Error).message);}}
  async function removeMember(member:WorkspaceMember){if(!window.confirm(`${member.display_name||member.email}님을 워크스페이스에서 제거할까요?`))return;try{await api(`/workspaces/${workspaceId}/members/${member.id}`,{method:'DELETE'});await load();notify('멤버를 제거했습니다.');}catch(error){notify((error as Error).message);}}
  async function revoke(invite:WorkspaceInvite){try{await api(`/workspaces/${workspaceId}/invites/${invite.id}`,{method:'DELETE'});await load();notify('초대를 취소했습니다.');}catch(error){notify((error as Error).message);}}
  const roleName=(value:string)=>({owner:'소유자',admin:'관리자',member:'멤버',guest:'게스트'}[value]||value);
  return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="dialog members-dialog"><div className="dialog-head"><div><span className="eyebrow">WORKSPACE PEOPLE</span><h2>멤버 및 초대</h2><p>팀원을 추가하고 워크스페이스 역할을 관리합니다.</p></div><button className="mini-icon" onClick={onClose}><X size={18}/></button></div>{canManage&&<div className="share-form member-invite-form"><input value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="동료 이메일 주소"/><select value={role} onChange={e=>setRole(e.target.value)}><option value="member">멤버</option><option value="guest">게스트</option>{canAssignAdmin&&<option value="admin">관리자</option>}</select><button className="primary" disabled={!email.trim()} onClick={invite}><Plus size={15}/> 초대</button></div>}{busy?<div className="members-loading">멤버 정보를 불러오는 중…</div>:<><div className="member-list-heading">워크스페이스 멤버 <span>{members.length}</span></div><div className="member-list">{members.map(member=><div className="member-row" key={member.id}><span className="comment-avatar">{(member.display_name||member.email).slice(0,1).toUpperCase()}</span><div className="member-identity"><b>{member.display_name||member.email.split('@')[0]}</b><small>{member.email}</small></div>{canManage&&member.role!=='owner'?<><select value={member.role} onChange={e=>changeRole(member,e.target.value)}>{canAssignAdmin&&<option value="admin">관리자</option>}<option value="member">멤버</option><option value="guest">게스트</option></select><button className="mini-icon" title="멤버 제거" onClick={()=>removeMember(member)}><X size={15}/></button></>:<span className="member-role">{roleName(member.role)}</span>}</div>)}</div>{invites.length>0&&<><div className="member-list-heading pending-heading">수락 대기 초대 <span>{invites.length}</span></div><div className="member-list">{invites.map(invite=><div className="member-row" key={invite.id}><span className="comment-avatar pending-avatar"><Clock3 size={13}/></span><div className="member-identity"><b>{invite.email}</b><small>{roleName(invite.role)} · {new Date(invite.created_at).toLocaleDateString('ko-KR')}</small></div>{canManage&&<button className="secondary-btn revoke-button" onClick={()=>revoke(invite)}>취소</button>}</div>)}</div></>}</>}<div className="dialog-note"><Users size={14}/> 워크스페이스 소유자 역할은 이 화면에서 변경할 수 없습니다.</div></div></div>;
}

function NotificationDialog({onClose,onOpen,onReadAll}:{onClose:()=>void;onOpen:(item:Notice)=>void;onReadAll:()=>void}){
  const[items,setItems]=useState<Notice[]>([]),[busy,setBusy]=useState(true);
  useEffect(()=>{api<{items:Notice[]}>('/notifications').then(result=>setItems(result.items)).catch(()=>setItems([])).finally(()=>setBusy(false));},[]);
  const unread=items.some(item=>!item.read_at);
  return <div className="overlay notification-overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="dialog notifications-dialog"><div className="dialog-head"><div><span className="eyebrow">INBOX</span><h2>알림</h2><p>댓글 언급과 페이지 공유 알림을 확인합니다.</p></div><div className="notification-actions">{unread&&<button className="text-button" onClick={()=>{void onReadAll();setItems(current=>current.map(item=>({...item,read_at:new Date().toISOString()})));}}>모두 읽음</button>}<button className="mini-icon" onClick={onClose}><X size={18}/></button></div></div><div className="notification-list">{busy?<div className="members-loading">알림을 불러오는 중…</div>:items.length===0?<div className="notification-empty"><Bell size={21}/><b>새 알림이 없습니다.</b><small>댓글에서 언급되거나 페이지가 공유되면 여기에 표시됩니다.</small></div>:items.map(item=><button className={`notification-row ${item.read_at?'read':''}`} key={item.id} onClick={()=>onOpen(item)}><span className="notification-avatar">{item.kind==='mention'?'@':<Share2 size={14}/>}</span><span className="notification-body"><b>{item.kind==='mention'?`${item.actor_name||item.actor_email.split('@')[0]}님이 댓글에서 언급했습니다.`:`${item.actor_name||item.actor_email.split('@')[0]}님이 페이지를 공유했습니다.`}</b><small>{item.page_title} · {new Date(item.created_at).toLocaleString('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small><span>{item.body}</span></span>{!item.read_at&&<i/>}</button>)}</div></div></div>;
}

function VersionDialog({page,canEdit,onClose,onSave,onRestore,notify}:{page:Page;canEdit:boolean;onClose:()=>void;onSave:(label:string)=>Promise<void>;onRestore:(content:any)=>Promise<void>;notify:(message:string)=>void}){
  const[items,setItems]=useState<PageVersion[]>([]),[label,setLabel]=useState('검토 시점'),[busy,setBusy]=useState(true),[working,setWorking]=useState(false);
  const load=async()=>{setBusy(true);try{const result=await api<{items:PageVersion[]}>(`/pages/${page.id}/versions`);setItems(result.items);}catch(error){notify((error as Error).message);}finally{setBusy(false);}};
  useEffect(()=>{void load();},[page.id]);
  async function save(){setWorking(true);try{await onSave(label.trim()||'수동 저장');setLabel('');await load();}catch(error){notify((error as Error).message);}finally{setWorking(false);}}
  async function restore(version:PageVersion){if(!window.confirm(`“${version.label||'자동 저장'}” 버전으로 복원할까요? 현재 내용은 복원 전 버전으로 먼저 저장됩니다.`))return;setWorking(true);try{const saved=await api<{content:any}>(`/pages/${page.id}/versions/${version.id}`);await onRestore(saved.content);onClose();}catch(error){notify((error as Error).message);}finally{setWorking(false);}}
  return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="dialog versions-dialog"><div className="dialog-head"><div><span className="eyebrow">PAGE HISTORY</span><h2>변경 이력</h2><p>최근 버전 60개를 보관하며 자동 저장은 편집이 있을 때 5분 간격으로 남깁니다.</p></div><button className="mini-icon" onClick={onClose}><X size={18}/></button></div>{canEdit&&<div className="version-save-row"><input value={label} onChange={e=>setLabel(e.target.value)} aria-label="버전 설명"/><button className="primary" disabled={working} onClick={save}><History size={14}/> 현재 버전 저장</button></div>}<div className="version-list">{busy?<div className="members-loading">변경 이력을 불러오는 중…</div>:items.length===0?<div className="notification-empty"><History size={21}/><b>저장된 버전이 없습니다.</b><small>수동 저장 또는 자동 저장 후 여기에 표시됩니다.</small></div>:items.map(version=><div className="version-row" key={version.id}><div className="version-marker"><History size={14}/></div><div className="version-info"><b>{version.label||'자동 저장'}</b><small>{version.actor_name||version.actor_email} · {new Date(version.created_at).toLocaleString('ko-KR')}</small></div>{canEdit&&<button className="secondary-btn" disabled={working} onClick={()=>restore(version)}>복원</button>}</div>)}</div></div></div>;
}

createRoot(document.getElementById('root')!).render(<App/>);
